<g stroke="#e2e8f0" stroke-width="2" fill="none"><path d="M220,190 q10,-10 20,0 q10,10 20,0 q10,-10 20,0"/><path d="M220,215 q10,-10 20,0 q10,10 20,0 q10,-10 20,0"/></g>
